using System.Collections.Generic;
namespace PixelArt {
static partial class HelpCatalog {
    static void Add(List<HelpEntry> all,string category,string id,string name,string description,string steps,string options,string shortcuts,string example,string tip,string keywords,string related,string icon=null){all.Add(new HelpEntry{Id=id,Name=name,Category=category,Icon=icon,Description=description,Steps=steps,Options=options,Shortcuts=shortcuts,Example=example,Tip=tip,Keywords=keywords,Related=related.Split(',')});}
    static List<HelpEntry> Build(){
        List<HelpEntry> a=new List<HelpEntry>();string c="Inicio";
        Add(a,c,"welcome","Bienvenido a Aropix","Crea personajes, objetos y paisajes píxel a píxel. Aropix es un editor local para Windows: toda esta ayuda funciona sin internet.","Empieza por Primeros pasos.|Explora una categoría a la izquierda o busca una palabra arriba.|Abre los enlaces de abajo para continuar aprendiendo.","Puedes mantener esta ventana abierta y volver al editor. Arrastra sus bordes para ampliarla.","F1 en el editor: ayuda de la herramienta o de la propiedad enfocada (opacidad, bloqueo, tamaños y centro del círculo). Aquí: Ctrl+F busca; Alt+Izquierda vuelve; Esc cierra.","Dibuja una pieza de ajedrez, añade una sombra y exporta una imagen PNG.","Guardar conserva el proyecto editable; exportar produce una imagen para utilizar fuera de Aropix.","principiante aprender tutorial","first,pencil,rectangle,selection,color,layernew,zoom,symv,new,shortcuts");
        Add(a,c,"about","¿Qué es Aropix?","Un editor de pixel art para Windows, con capas, figuras, selección y archivos editables.","Crea o abre un proyecto.|Dibuja a tu ritmo.|Guarda el proyecto y exporta una imagen cuando la necesites.","Pixel art significa construir imágenes mediante píxeles visibles y colores elegidos con intención.","","Un personaje de 32 × 32 píxeles puede ampliarse al exportarlo conservando bordes nítidos.","No necesitas conexión, cuentas ni navegador para dibujar o consultar esta ayuda.","acerca gratis offline internet","first,new,export");
        Add(a,c,"first","Primeros pasos","Aprende el recorrido básico: crear, dibujar, guardar y exportar.","Abre Archivo > Nuevo y elige nombre y dimensiones; prueba 32 × 32.|Selecciona Lápiz en Herramientas.|Haz clic en Elegir dentro de Color y acepta un color.|Haz clic o arrastra en el lienzo para dibujar.|Usa Archivo > Guardar para conservar un .pixelart.|Usa Archivo > Exportar PNG para generar una imagen.","El zoom acerca la vista sin cambiar los píxeles del dibujo.","B: lápiz · Ctrl+S: guardar · Rueda: zoom","Dibuja una pequeña moneda amarilla y guárdala como Moneda.pixelart.","Si te equivocas, Ctrl+Z deshace la última acción.","tutorial comenzar principiante","new,pencil,color,save,export");
        Add(a,c,"interface","Conocer la interfaz","El lienzo ocupa el centro; herramientas y propiedades están a la izquierda, Color y Capas a la derecha.","Elige una herramienta para ver sus opciones.|Cambia de documento con sus pestañas.|Consulta dimensiones, zoom y guardado automático en la barra inferior.","Ver > Paneles permite ocultar secciones. Los separadores ajustan los laterales y el reparto entre Color y Capas.","","Amplía Capas si tu escena contiene muchos elementos.","Ver > Restablecer distribución de paneles recupera la distribución inicial.","paneles interfaz opciones espacio","view,coordinates,layersorder,tabs");
        Add(a,c,"firstproject","Crear tu primer proyecto","El tamaño del lienzo determina cuántos píxeles puedes dibujar.","Abre Archivo > Nuevo.|Escribe un nombre y las dimensiones, por ejemplo 100 × 100.|Confirma y elige Lápiz para empezar.","La escala del resultado es distinta al tamaño del lienzo y al zoom.","Ctrl+N","Prueba un personaje pequeño antes de comenzar un paisaje de gran tamaño.","Puedes ampliar el lienzo después sin escalar lo dibujado.","nuevo iniciar resolución","new,dimensions,canvasresize");
        c="Herramientas de dibujo";
        Add(a,c,"pencil","Lápiz","Dibuja píxeles con el color seleccionado.","Selecciona Lápiz.|Elige un color, tamaño y forma de punta.|Haz clic para una marca o arrastra para un trazo.","Tamaño de 1 a 10 px; en Circular es el diámetro. Puntas Cuadrada (predeterminada) y Circular, sin suavizado. El tamaño es independiente del borrador y la punta se recuerda entre sesiones.","B · Alt + rueda: cambiar herramienta · Ctrl + rueda: cambiar punta","Traza el borde de un personaje con tamaño 1.","Acerca la vista para trabajar un píxel a la vez. La capa debe estar visible y desbloqueada.","dibujar pincel trazo","penciltips,eraser,color,quicktools,precision","Lápiz");
        Add(a,c,"eraser","Borrador","Elimina píxeles de la capa activa y deja transparencia.","Selecciona Borrador.|Ajusta su tamaño.|Haz clic o arrastra sobre la zona que quieras borrar.","Tamaño independiente de 1 × 1 a 10 × 10 px.","E · Alt + rueda: alternar dentro del grupo","Limpia píxeles que sobresalen del contorno.","Borrar no pinta de blanco: las capas inferiores pueden quedar a la vista.","borrar eliminar transparencia","pencil,deletepixels,quicktools","Borrador");
        Add(a,c,"bucket","Cubeta","Rellena una región conectada del mismo color en la capa activa.","Selecciona Cubeta.|Elige el color actual.|Haz clic dentro de la región cerrada.","Coincidencia exacta de color y alfa; conexión por lados, no por diagonales. No hay ajuste de tolerancia. Respeta la simetría activada.","G · Alt + rueda: Cubeta ↔ Cuentagotas","Rellena el interior de una moneda cuyo borde esté cerrado en esa misma capa.","Un hueco en el borde puede permitir que el relleno se extienda fuera. Los bordes de otras capas no cierran la región.","rellenar inundar contiguo conectividad","picker,color,quicktools,symv","Cubeta");
        Add(a,c,"picker","Cuentagotas","Selecciona un color de la composición visible del dibujo.","Activa Cuentagotas.|Haz clic en el color que quieras usar.|Vuelve a Lápiz o Cubeta para dibujar con él.","Toma el resultado visible de las capas; no cambia los píxeles ni crea historial.","I · Alt + rueda: Cuentagotas ↔ Cubeta","Recupera el tono de una hoja que ya dibujaste.","La opacidad de las capas influye en el color visible muestreado.","muestrear seleccionar color","color,palette,quicktools","Cuentagotas");
        Add(a,c,"pan","Mover vista","Desplaza la vista del lienzo sin mover los píxeles del dibujo.","Selecciona Mover vista.|Arrastra el lienzo para ver otra zona.","También puedes desplazar la vista con el botón central del ratón.","H · Botón central + arrastre","Recorre un paisaje ampliado sin modificar su contenido.","Alt + rueda no cambia esta herramienta porque su grupo tiene un solo elemento.","mano desplazamiento navegación","zoom,precision,quicktools","Mover vista");
        Add(a,c,"penciltips","Puntas del Lápiz","Elige una huella Cuadrada o Circular sin cambiar de herramienta.","Activa Lápiz.|En Forma de punta elige ■ o ●; la marca ✓ indica la activa.|También puedes usar Ctrl + rueda sobre el lienzo.|Dibuja con clic o arrastre.","Diámetro de 1 a 10 px dentro de N × N. Se incluyen los centros de píxel dentro del disco de radio N/2, sin suavizado. En tamaños impares el centro coincide con el píxel señalado; en pares queda medio píxel a su derecha y abajo, igual que el anclaje cuadrado. Los tamaños pequeños pueden coincidir con una huella cuadrada. La simetría refleja los píxeles de la huella. La preferencia se guarda fuera del proyecto.","Ctrl + rueda abajo: siguiente variante · arriba: anterior; recorrido circular.\nAlt + rueda: herramientas del grupo · rueda normal: zoom.","Con tamaño 7 y color azul, Ctrl + rueda cambia únicamente la forma de punta.","No cambia durante trazos ni operaciones pendientes. Ctrl + Alt + rueda da prioridad a Alt y ejecuta solo el cambio de herramienta. Sin variantes, Ctrl + rueda no hace nada. Sobre paneles se conserva su desplazamiento. El borrador sigue siendo cuadrado.","punta circular cuadrada diámetro ctrl rueda variantes","pencil,quicktools,zoom");
        c="Figuras geométricas";
        Add(a,c,"rectangle","Rectángulo","Dibuja un rectángulo delimitado por dos esquinas.","Abre Figuras y elige Rectángulo.|Elige relleno o contorno y su grosor.|Haz clic en una esquina y después en la opuesta.","Relleno opcional y contorno de 1 a 10 px hacia el interior de los límites elegidos.","Flechas: ajustar extremo · Enter: fijar punto · Esc: cancelar","Crea una ventana o un bloque del escenario.","Un cuadrado es un rectángulo con igual ancho y alto.","cuadrado cuadrilátero figura","fill,outline,precision,quicktools","Rectángulo");
        Add(a,c,"circle","Círculo","Dibuja un círculo a partir de su centro y un punto que define el radio.","Abre Figuras y elige Círculo.|Configura centro, relleno y grosor.|Marca el centro.|Ajusta el radio y confirma el siguiente punto.","Centro 1 × 1 para diámetros impares o 2 × 2 para pares. Grosor de 1 a 10 px si no lleva relleno.","Flechas: ajustar radio · Enter: confirmar · Esc: cancelar","Dibuja una rueda de diámetro par para que encaje en una base de ancho par.","El contorno queda dentro del límite exterior elegido.","redondo radio diámetro","circlecenter,fill,outline,quicktools","Círculo");
        Add(a,c,"triangle","Triángulo","Construye una figura mediante tres vértices.","Abre Figuras y selecciona Triángulo.|Ajusta relleno o contorno.|Marca sus tres vértices; el tercero completa la figura.","Relleno opcional; contorno interior de 1 a 10 px.","Flechas y Enter: colocar vértices · Esc: cancelar","Crea el tejado de una casa.","Puedes revisar la vista previa antes de colocar el último vértice.","polígono tres puntos","fill,outline,quicktools","Triángulo");
        Add(a,c,"line","Línea recta","Une un punto inicial y uno final con un trazo recto.","Abre Figuras y elige Línea recta.|Ajusta el grosor.|Marca el inicio y el final.","Grosor de 1 a 10 px. La opción de relleno no se aplica a una línea.","Flechas: ajustar extremo · Enter: confirmar · Esc: cancelar","Traza una barandilla o un borde diagonal.","El punto inicial se mantiene al ajustar el extremo y desplazar la vista.","segmento trazo recto","precision,outline,quicktools","Línea recta");
        Add(a,c,"fill","Relleno de figuras","Decide si una figura pinta su interior o solo su borde.","Elige Rectángulo, Círculo o Triángulo.|En Opciones, marca Figura con relleno.|Coloca los puntos de la figura.","Desmarca la casilla para dibujar un contorno. No se aplica a Línea recta.","","Crea un bloque sólido para una plataforma.","Cambiar esta opción configura las próximas figuras; no modifica las que ya dibujaste.","hueco sólido interior","rectangle,circle,triangle,outline");
        Add(a,c,"outline","Grosor de contornos","Controla el espesor del borde de las figuras sin relleno.","Selecciona una figura.|Desmarca Figura con relleno.|Elige el grosor y coloca la figura.","De 1 a 10 píxeles; el contorno se traza hacia dentro. En Línea recta ajusta directamente el grosor.","","Dibuja un marco grueso que empiece exactamente en el borde del lienzo.","Un grosor grande puede ocupar todo el interior de una figura pequeña.","borde espesor ancho","fill,line,circle");
        Add(a,c,"circlecenter","Centro del círculo: par e impar","Permite construir círculos tanto de diámetro par como impar.","Activa Círculo.|En Centro del círculo, elige 1 × 1 — impar o 2 × 2 — par.|Coloca centro y radio.","El centro 2 × 2 distribuye la simetría entre cuatro píxeles; 1 × 1 usa un píxel central.","","Usa centro par para una moneda que deba ocupar un ancho par.","El tamaño depende también del radio que elijas.","paridad diámetro centro","circle,precision");
        c="Selección y transformaciones";
        Add(a,c,"selection","Selección rectangular","Delimita una parte del dibujo para copiarla, moverla o transformarla.","Activa Selección.|Arrastra desde una esquina hasta la opuesta.|Usa la barra contextual o el menú Selección.","Opera sobre la capa activa. Para editar, la capa debe estar visible y desbloqueada.","M · Alt + rueda: Selección rectangular ↔ Varita mágica","Selecciona una pieza del tablero para colocarla en otra casilla.","El marco de selección no incluye automáticamente el contenido de otras capas.","seleccionar región área","wand,move,copy,rotateR,flipH,resizeSelection,quicktools","Selección");
        Add(a,c,"copy","Copiar y pegar","Reutiliza una selección en el mismo proyecto o en otro abierto en Aropix.","Selecciona el contenido y copia.|Activa el proyecto y capa de destino.|Pega y ajusta la posición.|Confirma el pegado.","El editor utiliza su copia interna de selección; para importar archivos de imagen usa Importar imagen.","Ctrl+C: copiar · Ctrl+V: pegar","Repite varias ventanas de una casa sin volver a dibujarlas.","Copiar no modifica el origen. Pegar requiere una capa visible y desbloqueada.","duplicar portapapeles","confirm,move,tabs");
        Add(a,c,"confirm","Confirmar o cancelar pegado","Revisa el contenido temporal antes de incorporarlo a la capa.","Pega o transforma una selección.|Ajusta su posición o tamaño.|Pulsa Confirmar para aplicarlo o Cancelar para descartarlo.","La barra contextual aparece solo cuando corresponde. Deseleccionar confirma primero el contenido pendiente.","Enter: confirmar · Esc: cancelar","Prueba un giro y cancélalo si no encaja.","El cambio manual de herramienta puede confirmar contenido pendiente; confirma o cancela explícitamente antes de cambiar.","aceptar pendiente vista previa","copy,resizeSelection,selection");
        Add(a,c,"deletepixels","Eliminar contenido seleccionado","Borra los píxeles dentro de la selección en la capa activa.","Activa Selección y delimita el área.|Usa Selección > Borrar área seleccionada.","Deja transparencia. No elimina la capa. Respeta el bloqueo y la visibilidad.","Supr con Selección activa · Ctrl+Z: deshacer","Elimina un objeto aislado dejando el fondo de otra capa intacto.","Si quieres borrar la capa completa, utiliza Eliminar capa.","borrar eliminar suprimir","selection,eraser,layerdelete");
        Add(a,c,"move","Mover selección","Desplaza una parte de la capa sin volver a dibujarla.","Delimita el área con Selección.|Arrastra dentro de ella hasta el destino.|Con flechas, ajusta y confirma con Enter.","El arrastre se aplica al soltar; los ajustes con flechas pueden quedar pendientes de confirmar.","Flechas: 1 px · Mayús+flecha: 10 px · Enter: confirmar","Mueve una pieza dos píxeles para alinearla.","Mover vista desplaza la cámara; Mover selección modifica el dibujo.","trasladar posición mover","selection,confirm,pan");
        string[] ids={"rotateR","rotateL","flipH","flipV","resizeSelection"};string[] names={"Girar 90° a la derecha","Girar 90° a la izquierda","Voltear horizontalmente","Voltear verticalmente","Cambiar tamaño de una selección"};string[] desc={"Rota la selección un cuarto de vuelta en sentido horario.","Rota la selección un cuarto de vuelta en sentido antihorario.","Invierte izquierda y derecha del contenido seleccionado.","Invierte arriba y abajo del contenido seleccionado.","Cambia las dimensiones del contenido seleccionado, conservando bordes nítidos."};
        for(int i=0;i<ids.Length;i++)Add(a,c,ids[i],names[i],desc[i],"Delimita el contenido con Selección.|Abre Selección > Transformar selección y elige "+(i==4?"Cambiar tamaño…":names[i])+".|"+(i==4?"Indica ancho y alto y pulsa Aplicar.|":"")+"Revisa la vista previa y confirma.",i==4?"Ancho y alto de 1 a 2048 px; escalado sin suavizado.":"Requiere selección aplicable y capa editable. También está disponible en la barra contextual.","Enter: confirmar · Esc: cancelar",""+(i<2?"Orienta una baldosa en otra dirección.":i<4?"Obtén la versión reflejada de un adorno.":"Amplía una estrella seleccionada sin cambiar el lienzo."),"La transformación afecta a la selección, no a todas las capas.",i<2?"rotar rotación giro":i<4?"reflejar espejo invertir":"escalar redimensionar","selection,confirm,canvasresize");
        Add(a,c,"wand","Varita mágica","Selecciona una región irregular de píxeles contiguos con el mismo color y transparencia en la capa activa.","Abre el desplegable de Selección y elige Varita mágica, o usa Selección > Varita mágica.|Activa la capa que quieras analizar.|Haz clic sobre un píxel de la región.|Mantén Control y haz clic para añadir otras regiones; mantén Alt y haz clic para restarlas.|Usa Copiar, Mover, Borrar o Transformar selección para trabajar con ella.","Coincidencia exacta RGBA: tolerancia fija 0. Solo conecta arriba, abajo, izquierda y derecha; nunca diagonales. Los píxeles con alfa 0 se consideran iguales aunque su RGB invisible difiera. Analiza la capa activa, no la composición. Se pueden seleccionar capas ocultas o bloqueadas; las operaciones de edición siguen requiriendo una capa visible y desbloqueada.","Control + clic: añadir región · Alt + clic: restar región\nAlt + rueda: Selección rectangular ↔ Varita mágica\nCtrl+C/V: copiar/pegar · Supr: borrar · Flechas: mover · Enter: confirmar · Esc: cancelar","En un tablero de ajedrez, una casilla negra no conecta con otras casillas negras que solo se tocan por las esquinas.","Los contornos incluyen los huecos internos. Copiar, borrar, mover, girar, voltear y redimensionar respetan la máscara irregular, no solo su rectángulo exterior. Arrastra dentro de la región seleccionada para moverla; pulsa fuera para seleccionar otra. La selección es temporal y no se exporta ni se guarda. Control + clic añade regiones y Alt + clic las resta, incluso si tienen otro color. La conectividad de cada región sigue siendo de cuatro lados. Sin selección, Control inicia una y Alt no hace nada; restar todo deselecciona. Control + Alt juntos no cambian la selección. No se combinan regiones mientras hay un pegado o transformación pendiente: confirma o cancela primero. No hay tolerancia configurable. Alt + rueda espera a que confirmes o canceles operaciones pendientes.","varita mágica magic wand contiguo región máscara conectividad cuatro diagonales transparencia sumar añadir restar quitar control alt","selection,copy,move,rotateR,flipH,resizeSelection,quicktools","Varita mágica");
        c="Color y paletas";
        Add(a,c,"color","Seleccionar color","Elige el color con el que dibujarán las herramientas.","Haz clic en la muestra actual o en Elegir dentro de Color.|Selecciona un tono y acepta.|También puedes escribir un código hexadecimal en el campo de color.","Puedes elegir un color de las paletas o tomarlo del dibujo con Cuentagotas.","I: cuentagotas","Elige #FFCC00 para una moneda dorada.","Cambiar el color actual no recolorea los píxeles ya dibujados.","selector rgb hexadecimal tono","currentcolor,palette,picker");
        Add(a,c,"currentcolor","Color actual","La muestra de Color indica el tono que usarás en los próximos trazos.","Consulta la muestra del panel Color.|Haz clic sobre ella si quieres cambiarla.","El campo hexadecimal muestra y permite introducir el color.","","Comprueba el color antes de rellenar una región.","El borrador elimina píxeles independientemente del color actual.","muestra tinta","color,bucket");
        Add(a,c,"palette","Paleta del proyecto","Guarda una colección de colores para este dibujo.","Elige un color.|Pulsa + Añadir color actual.|Haz clic en una muestra guardada para reutilizarla.","Hasta 64 colores. La paleta se guarda dentro del .pixelart.","Clic derecho sobre una muestra: quitarla","Conserva los tonos de piel y ropa de un personaje.","Eliminar una muestra no modifica los píxeles que usan ese color.","colores guardar colección","paletteadd,paletteremove,save");
        Add(a,c,"paletteadd","Añadir colores","Incorpora el color actual a la paleta del proyecto.","Selecciona el tono que quieras conservar.|Pulsa + Añadir color actual en Color.","Si ya existe no se duplica; el máximo es 64 colores.","","Añade tres tonos de verde para tu paisaje.","Guarda el proyecto para conservar la paleta.","agregar muestra","palette,color");
        Add(a,c,"paletteremove","Eliminar colores","Quita una muestra de la paleta sin alterar el dibujo.","Localiza la muestra en Paleta del proyecto.|Haz clic derecho sobre ella.","La eliminación afecta a la paleta del proyecto, no a los colores básicos.","Clic derecho","Quita un tono de prueba que ya no usarás.","Los píxeles pintados con él conservan su color.","borrar quitar muestra","palette,paletteadd");
        Add(a,c,"recent","Colores recientes","Permite recuperar colores utilizados recientemente al dibujar.","Expande Colores recientes en el panel Color.|Haz clic en una muestra.","Muestra hasta 12 colores recientes; la sección se puede plegar.","","Recupera el último tono de una sombra.","Añade los tonos importantes a la paleta del proyecto para conservar una colección estable.","historial tonos","palette,basiccolors");
        Add(a,c,"basiccolors","Colores básicos","Ofrece una colección inicial de colores listos para usar.","Expande Colores básicos.|Haz clic en una muestra para convertirla en el color actual.","Puedes plegar la sección para liberar espacio; se recuerda su estado.","","Empieza con negro y blanco para esbozar una figura.","Utiliza Elegir para obtener otros tonos.","preseleccionados paint","color,recent");
        c="Capas y efectos";
        Add(a,c,"layernew","Crear capas","Separa fondo, personajes y objetos en superficies transparentes independientes.","Usa Capas > Nueva capa o el botón +.|Selecciona la nueva capa y dibuja en ella.","Máximo de 16 capas. La nueva se coloca sobre la activa.","","Dibuja el personaje encima de un fondo en otra capa.","La capa seleccionada recibe los trazos.","agregar nueva transparencia","layerrename,layersorder,opacity");
        Add(a,c,"layerrename","Renombrar capas","Pon nombres que expliquen el contenido de cada capa.","Selecciona la capa.|Usa Capas > Renombrar capa….|Escribe un nombre y acepta.","También está disponible en el menú contextual de la capa.","","Llama Fondo, Torre y Sombra a las capas de una escena.","Los nombres claros facilitan elegir la capa correcta.","nombre cambiar","layernew,layersorder");
        Add(a,c,"layerduplicate","Duplicar capas","Crea una copia independiente de la capa activa.","Selecciona la capa.|Usa Capas > Duplicar capa o ×2.","Conserva píxeles, opacidad, visibilidad y bloqueo del origen. Requiere espacio bajo el límite de 16 capas.","","Prueba variaciones de un personaje sobre una copia.","Si la copia está bloqueada, desbloquéala antes de editar.","copiar réplica","shadow,lock,layerdelete");
        Add(a,c,"layersorder","Reorganizar capas","Cambia qué elementos quedan delante y detrás.","Selecciona el nombre de una capa.|Arrástralo a otra posición, o usa Capas > Subir capa / Bajar capa.","Arriba en la lista significa delante en la composición.","Arrastrar el nombre de la capa","Coloca una sombra debajo de una pieza de ajedrez.","Arrastra el nombre, no la casilla de visibilidad.","reordenar orden arrastre posición","shadow,visible,layernew");
        Add(a,c,"visible","Mostrar y ocultar capas","Decide qué capas se ven en el lienzo y en la imagen compuesta.","Localiza la casilla junto a la capa.|Márcala para mostrarla o desmárcala para ocultarla.","Ocultar no borra los píxeles. Las capas ocultas se conservan en el proyecto.","","Oculta una referencia para revisar el resultado limpio.","No se puede dibujar en una capa oculta; Crear sombra sí puede leer su contenido.","visibilidad transparencia","lock,shadow,exportlayers");
        Add(a,c,"lock","Bloquear capas","Protege el contenido de una capa contra ediciones accidentales.","Selecciona la capa.|Marca Bloquear capa.|Desmárcalo cuando quieras editarla.","El indicador [B] identifica el bloqueo. Impide editar píxeles, eliminar y combinar; permite cambiar orden, visibilidad y opacidad.","","Bloquea una fotografía importada antes de dibujar encima.","Crear sombra está permitido porque no modifica el origen.","proteger referencia desbloquear","import,opacity,shadow");
        Add(a,c,"opacity","Opacidad","Ajusta la transparencia general de una capa sin cambiar sus píxeles.","Selecciona la capa.|Modifica Opacidad en el panel Capas.","0%: invisible; 100%: cobertura original. El alfa individual se conserva y se combina con este porcentaje.","","Baja una referencia al 30% para dibujar encima.","La capa sigue existiendo al 0%; no equivale a borrarla.","transparencia alfa semitransparente","shadow,visible,import");
        Add(a,c,"merge","Combinar capas","Une la capa activa con la que está inmediatamente debajo.","Muestra y desbloquea ambas capas.|Selecciona la superior.|Usa Capas > Combinar con la inferior.","La apariencia compuesta se incorpora a una capa al 100% de opacidad. La capa inferior no puede estar bloqueada.","Ctrl+Z: deshacer","Une detalles terminados para liberar una capa.","Guarda una copia del proyecto si quieres conservar sus elementos por separado.","fusionar unir","layerduplicate,save,opacity");
        Add(a,c,"layerdelete","Eliminar capas","Quita la capa activa del proyecto.","Selecciona una capa desbloqueada.|Usa Capas > Eliminar capa o el botón −.","Si eliminas la última, queda una capa vacía para poder seguir trabajando.","Ctrl+Z: deshacer","Retira una referencia cuando hayas terminado.","Ocultar es suficiente si solo quieres dejar de verla temporalmente.","borrar quitar capa","visible,layernew");
        Add(a,c,"importlayer","Importar imágenes como capas","Añade una imagen PNG/JPG para usarla como referencia o parte del dibujo.","Abre Capas > Importar imagen….|Selecciona el archivo.|Ajusta dimensiones y opacidad y confirma.","Se centra en el lienzo y se recorta lo que queda fuera. Requiere menos de 16 capas.","","Importa un boceto y dibuja encima en otra capa.","Bloquea la referencia para no modificarla por accidente.","png jpg jpeg fotografía referencia","import,importsize,lock");
        Add(a,c,"shadow","Crear sombra","Genera una réplica monocromática en una nueva capa inmediatamente debajo del origen, con vista previa temporal en el lienzo.","Selecciona la capa original.|Abre Capas > Crear sombra… o haz clic derecho sobre la capa y elige Crear sombra….|Elige un color: la vista previa cambia al aceptar el selector.|Ajusta opacidad y desplazamientos X e Y; observa el lienzo.|Pulsa Crear sombra para añadirla o Cancelar para salir sin cambios.","Por defecto: negro #000000, 15%, X +1 px, Y +1 px. Opacidad 0–100%; desplazamientos −2048 a +2048. +X mueve a la derecha y +Y hacia abajo. El exceso se recorta, sin ampliar el lienzo. La nueva capa se llama Sombra de [nombre], queda visible y desbloqueada.","Esc en la ventana: cancelar · Ctrl+Z / Ctrl+Y después de crear: deshacer / rehacer","Con una torre de ajedrez, usa negro al 15% y X=2, Y=2 para añadir profundidad detrás de la pieza.","No modifica el origen, incluso si está oculto o bloqueado. Conserva el alfa individual sin multiplicar la opacidad original. La sombra es independiente: puedes mover su contenido con Selección, editar, bloquear, ocultar o eliminar la capa. La creación ocupa una acción de historial. Se deshabilita al alcanzar 16 capas o con operaciones pendientes. Una capa vacía muestra un aviso. Cancelar o cerrar retira la vista previa sin modificar el dibujo.","transparencia silueta efecto alfa vista previa","opacity,layersorder,layerduplicate,color,move");
        c="Lienzo y visualización";
        Add(a,c,"animations","Animaciones de interfaz","Transiciones breves al abrir ventanas, plegar paneles y pasar el cursor sobre controles.","Abre Ver > Animaciones de interfaz.|Activa o desactiva la opción; la preferencia se conserva al cerrar Aropix.","Se omiten en alto contraste, escritorio remoto y cuando Windows deshabilita las animaciones. Los cierres y el cambio de proyecto son inmediatos. Los laterales con desplazamiento y los paneles flotantes se pliegan sin transición.","","Desactívalas para que todos los estados se apliquen inmediatamente.","Las transiciones no modifican el dibujo ni el historial.","movimiento accesibilidad efectos fluidez","view,zoom");
        Add(a,c,"dimensions","Dimensiones del lienzo","El ancho y alto indican cuántos píxeles editables tiene el proyecto.","Consulta las dimensiones en la barra inferior.|Decide si necesitas ampliar el área o solo verla más grande.","Hasta 2048 × 2048 px. El zoom cambia la vista; la escala de exportación cambia el tamaño del PNG.","","100 × 100 contiene 10 000 posiciones de píxel por capa.","Para añadir paisaje usa Cambiar tamaño del lienzo; para verlo más cerca usa Zoom.","resolución tamaño ancho alto","canvasresize,zoom,export");
        Add(a,c,"canvasresize","Cambiar tamaño del lienzo","Añade o recorta espacio sin escalar el dibujo.","Abre Lienzo > Cambiar tamaño del lienzo….|Indica ancho y alto.|Elige dónde conservar el dibujo y aplica.","Nueve anclajes; afecta a todas las capas, incluso bloqueadas. El espacio nuevo es transparente. Reducir recorta el exterior.","Ctrl+Z: deshacer","Elige Izquierda para conservar el dibujo a la izquierda y añadir espacio a la derecha.","Redimensionar una selección es una operación diferente.","ampliar recortar dimensiones","dimensions,resizeSelection");
        Add(a,c,"zoom","Zoom","Acerca o aleja la vista sin cambiar el archivo ni sus píxeles.","Coloca el cursor sobre el lienzo.|Gira la rueda o utiliza los botones − y + inferiores.|Usa Ver > Ajustar vista para encajar el dibujo.","Zoom entre 12,5% y 3200%. La escala de exportación es independiente.","Rueda sin modificadores: zoom","Acerca un ojo de un personaje para corregir un píxel.","Alt + rueda cambia herramientas del grupo; Ctrl + rueda cambia variantes. Ninguna combinación hace zoom.","rueda acercar alejar escala visual","quicktools,pan,export");
        Add(a,c,"viewpan","Desplazamiento de vista","Recorre distintas zonas del lienzo ampliado.","Mantén el botón central y arrastra, o activa Mover vista.|Suelta al llegar a la zona deseada.","No desplaza las capas ni modifica el dibujo.","H: Mover vista","Recorre los extremos de un paisaje grande.","Ajustar vista vuelve a mostrar el proyecto completo.","scroll navegar cámara","pan,zoom");
        Add(a,c,"grid","Cuadrícula","Distingue los límites de los píxeles al trabajar con suficiente zoom.","Activa Ver > Cuadrícula o su acceso rápido.|Acerca el lienzo para verla con claridad.","Se dibuja a partir de un zoom de 800% y usa contraste para distinguirse sobre colores oscuros y claros.","","Comprueba la alineación de un borde de un píxel.","La cuadrícula no aparece en el PNG exportado.","rejilla bordes","zoom,coordinates");
        Add(a,c,"coordinates","Coordenadas","Muestra la posición del cursor dentro del lienzo.","Abre Ver > Coordenadas.|Elige No mostrar, En la barra inferior o Junto al cursor.","Las opciones son excluyentes. Las coordenadas empiezan en X=0, Y=0 en la esquina superior izquierda.","","Encuentra el píxel 0,0 para comenzar un borde exacto.","Elige la barra inferior si la etiqueta cerca del cursor tapa detalles.","posición mouse ratón xy","precision,grid");
        Add(a,c,"view","Opciones de visualización","Organiza el espacio de trabajo según lo que necesites.","Abre Ver > Paneles para mostrar u ocultar secciones.|Arrastra separadores para ajustar espacio.|Usa Restablecer distribución de paneles si quieres empezar de nuevo.","Paneles Herramientas, Opciones, Color y Capas; se pueden plegar, mover y hacer flotantes. La distribución se recuerda entre sesiones.","","Oculta Colores básicos y aumenta el alto de Capas.","La ayuda no sustituye al lienzo y puedes dejarla abierta mientras editas.","paneles distribución restaurar ventanas","interface,coordinates,grid");
        c="Simetría";
        Add(a,c,"symv","Simetría vertical","Refleja el dibujo de izquierda a derecha respecto a un eje vertical.","Activa Dibujo > Simetría > Simetría vertical.|Dibuja en un lado para obtener el reflejo.","Se puede combinar con simetría horizontal. Usa la posición del eje configurada.","","Dibuja las dos mitades de una cara a la vez.","Los reflejos fuera del lienzo se recortan. No refleja retroactivamente lo ya dibujado.","espejo reflejar izquierda derecha","symh,axes,centeraxes");
        Add(a,c,"symh","Simetría horizontal","Refleja el dibujo de arriba a abajo respecto a un eje horizontal.","Activa Dibujo > Simetría > Simetría horizontal.|Dibuja a un lado del eje.","Puede estar activa junto a la vertical para producir cuatro posiciones simétricas.","","Crea un adorno con mitades superior e inferior iguales.","La selección, importación y las sombras son operaciones independientes del reflejo de trazos.","espejo reflejar arriba abajo","symv,axes");
        Add(a,c,"axes","Posición de los ejes","Elige dónde se refleja el dibujo en lugar de usar siempre el centro.","Abre Dibujo > Simetría > Posición de los ejes….|Configura X para el eje vertical y Y para el horizontal.|Aplica y dibuja con la simetría activada.","Admite posiciones de medio píxel para ejes entre píxeles. La configuración se guarda en el proyecto.","","Sitúa el eje de un personaje a un lado de un lienzo ancho.","La guía muestra el eje de cada simetría activada.","mover eje mitad posición","symv,symh,centeraxes");
        Add(a,c,"centeraxes","Centrar ambos ejes","Devuelve los ejes de simetría al centro automático del lienzo.","Abre Dibujo > Simetría > Centrar ambos ejes.","Restablece ambas posiciones. Las casillas de simetría controlan si se dibuja el reflejo.","","Vuelve al centro después de dibujar un objeto desplazado.","El centrado automático se adapta si cambias las dimensiones del lienzo.","restablecer ejes","axes,canvasresize");
        c="Archivos y proyectos";
        Add(a,c,"new","Crear proyecto","Inicia un documento con su propio lienzo y capas.","Abre Archivo > Nuevo.|Escribe nombre, ancho y alto y configura la escala del resultado.|Confirma para empezar.","Lienzo de 1 a 2048 px por lado. La exportación no puede superar 8192 px por lado.","Ctrl+N","Crea un paisaje separado del proyecto del personaje.","Puedes trabajar con varios proyectos mediante pestañas.","nuevo crear archivo","firstproject,dimensions,tabs");
        Add(a,c,"open","Abrir proyecto","Recupera un archivo editable de Aropix.","Abre Archivo > Abrir….|Selecciona un archivo .pixelart.","Se conservan capas, paleta y propiedades guardadas. Se mantiene la compatibilidad con proyectos anteriores.","Ctrl+O","Continúa un dibujo guardado ayer.","Para una imagen PNG o JPG usa Importar imagen, no Abrir proyecto.","cargar archivo","format,import,tabs");
        Add(a,c,"save","Guardar proyecto","Conserva el documento editable con sus capas y colores.","Usa Archivo > Guardar.|Si es nuevo, elige nombre y ubicación.|Para otra copia, usa Archivo > Guardar como….","Un asterisco junto al nombre indica cambios pendientes. Guardar como crea otro archivo editable.","Ctrl+S · Ctrl+Mayús+S: guardar como","Guarda una copia antes de combinar capas.","Exportar PNG no sustituye al guardado del proyecto editable.","guardar como copia disco","format,autosave,export");
        Add(a,c,"format","Formato .pixelart","Es el archivo de proyecto de Aropix, diseñado para seguir editando.","Guarda con Archivo > Guardar.|Reabre el archivo con Archivo > Abrir.","Conserva píxeles y propiedades de capas, paleta, dimensiones y simetría. La distribución de paneles se guarda aparte como preferencia.","Ctrl+S / Ctrl+O","Conserva por separado fondo, torre y sombra para retocarlos después.","El historial de deshacer es de la sesión de trabajo; no debes tratarlo como una copia permanente del proyecto.","compatibilidad formato archivo","save,open,export");
        Add(a,c,"tabs","Múltiples proyectos","Trabaja con varios documentos usando pestañas.","Crea o abre otro proyecto.|Haz clic en su pestaña para activarlo.|Guarda sus cambios antes de cerrarlo.","Cada proyecto conserva capas, historial y vista. Al reabrir Aropix se recuperan pestañas y vistas; se respetan los cambios descartados expresamente al cerrar.","Ctrl+Tab: siguiente · Ctrl+W, X o clic central: cerrar proyecto","Copia un objeto de una pestaña y pégalo en el escenario de otra.","Revisa qué pestaña está activa antes de pegar o guardar. Al cerrar un proyecto con cambios se conserva la decisión de guardar, descartar o cancelar.","pestañas sesión restaurar proyectos","copy,save,autosave");
        Add(a,c,"import","Importar PNG/JPG","Añade una imagen externa como una nueva capa del proyecto actual.","Usa Archivo > Importar imagen… o la opción del menú Capas.|Elige PNG, JPG o JPEG.|Configura tamaño y opacidad y pulsa Importar.","No reemplaza el lienzo. Se centra y recorta lo que sobresale. Admite hasta 16 capas.","","Usa una fotografía como referencia debajo de un dibujo.","PNG puede contener transparencia; JPG no almacena un canal alfa.","png jpg jpeg abrir fotografía transparencia","importsize,drop,lock");
        Add(a,c,"drop","Arrastrar imágenes para importarlas","Importa imágenes arrastrándolas desde el Explorador de Windows.","Arrastra un PNG o JPG a Aropix.|Ajusta las dimensiones en la ventana de importación.|Confirma para crear la capa.","Utiliza el mismo procedimiento y límites que Importar imagen.","Arrastrar archivo desde el Explorador","Añade un boceto sin buscarlo de nuevo en el diálogo de archivos.","Revisa la pestaña de destino antes de soltarlo.","arrastre drag drop png jpg","import,importsize");
        Add(a,c,"importsize","Seleccionar dimensiones de importación","Controla el tamaño y aspecto de la imagen antes de añadirla.","Inicia una importación.|Indica ancho y alto.|Elige si conservas proporción, opacidad y suavizado.|Confirma.","Dimensiones de 1 a 2048 px. Opacidad inicial 50%. Sin suavizado mantiene píxeles nítidos; Suavizar está pensado para fotografías.","","Reduce un boceto grande para que quepa en tu lienzo.","La imagen queda centrada y el exterior se recorta; después puedes mover o escalar su contenido con Selección.","escalar referencia tamaño png jpg","import,resizeSelection,opacity");
        Add(a,c,"export","Exportar PNG","Genera una imagen de la composición visible para usarla fuera de Aropix.","Abre Archivo > Exportar PNG….|Elige la escala y revisa las dimensiones resultantes.|Elige nombre y ubicación.","Escala entera hasta ×32, limitada a 8192 px por lado. Conserva transparencia y bordes nítidos. No incluye cuadrícula ni guías.","","Exporta un sprite de 32 × 32 a ×4 para obtener 128 × 128.","Guarda también el .pixelart para conservar las capas editables. Una exportación correcta muestra un aviso que puedes cerrar; se oculta tras unos segundos y pausa su tiempo mientras lo señalas. Los errores requieren que cierres su mensaje explícitamente.","png imagen resolución salida","save,exportlayers,zoom");
        Add(a,c,"exportlayers","Exportar capas individualmente","Crea un PNG separado por cada capa elegida.","Abre Archivo > Exportar capas como PNG….|Elige las opciones de capas, escala y opacidad.|Selecciona el destino.","Por defecto exporta las visibles; puedes incluir ocultas y elegir si se respeta la opacidad. Cada PNG usa todo el lienzo. Crea una carpeta nueva para evitar sobrescribir resultados.","","Exporta fondo, personaje y sombra por separado para tu videojuego.","Las imágenes mantienen la alineación del lienzo aunque cada objeto ocupe solo una parte.","png exportación individual archivos","export,visible,opacity");
        Add(a,c,"autosave","Guardado automático","Guarda periódicamente para reducir la pérdida de trabajo.","Abre Archivo > Guardado automático.|Actívalo y entra en Configurar….|Elige un intervalo predefinido o escribe un tiempo y aplica.","Desde 1 segundo hasta 24 horas. Acepta 30 segundos, 2 minutos o 1,5 min; sin unidad interpreta minutos. Actualiza archivos existentes y guarda recuperación de proyectos nuevos. Espera a que terminen operaciones pendientes.","Ctrl+S: guardar inmediatamente","Configura 2 minutos para una sesión larga.","La barra inferior muestra su estado real y cambios pendientes. El autoguardado de un proyecto con archivo actualiza ese archivo; no es un historial de versiones. Los archivos internos se guardan en %LocalAppData%\\Aropix. Al iniciar se compara la sesión y la recuperación válidas de esa carpeta y de la ubicación antigua; los originales no se eliminan.","recuperación guardar tiempo segundos minutos automático","save,tabs");
        c="Atajos y controles";
        Add(a,c,"shortcuts","Atajos de teclado","Consulta los accesos rápidos disponibles en el editor.","Da el foco al lienzo para trabajar con herramientas.|Usa el atajo correspondiente.|Si escribes en un campo, sus teclas de edición conservan su función.","Los giros y volteos se eligen en Selección > Transformar selección; no tienen una combinación propia asignada.","B: lápiz · E: borrador · G: cubeta · I: cuentagotas\nM: selección · H: mover vista\nCtrl+N/O/S: nuevo/abrir/guardar\nCtrl+Mayús+S: guardar como\nCtrl+Z/Y: deshacer/rehacer · Ctrl+C/V: copiar/pegar\nCtrl+Tab: siguiente proyecto · Ctrl+W: cerrar proyecto\nFlechas: 1 px · Mayús+flecha: 10 px · Enter: confirmar\nEsc: cancelar · Supr: borrar selección\nRueda: zoom · Alt + rueda: herramientas · Ctrl + rueda: variantes\nF1: ayuda de la herramienta actual\nVarita: Control + clic añade; Alt + clic resta","Alterna B y E para corregir rápidamente un contorno.","Las acciones deshabilitadas no se pueden ejecutar en el estado actual.","teclado combinación ctrl shift enter","mouse,precision,selectionkeys,quicktools");
        Add(a,c,"mouse","Controles del ratón","Dibuja, navega y elige colores sin abandonar el lienzo.","Haz clic o arrastra con la herramienta activa.|Usa la rueda para zoom.|Mantén el botón central y arrastra para mover la vista.","Con Varita, Control + clic añade una región y Alt + clic la resta. Alt + rueda conserva el cambio de herramienta. Botón derecho con flechas activa precisión. En la paleta, clic derecho quita una muestra; en Capas abre sus acciones.","Alt + rueda: herramienta del grupo · Ctrl + rueda: variantes","Desplaza la vista con el botón central sin dejar Lápiz.","La rueda sobre listas y paneles conserva su desplazamiento habitual.","mouse rueda clic botones","zoom,quicktools,precision");
        Add(a,c,"wheelzoom","Zoom mediante rueda","La rueda normal acerca y aleja el lienzo.","Coloca el cursor sobre el lienzo.|Gira hacia arriba para acercar o hacia abajo para alejar.","Sin Ctrl ni Alt se mantiene el zoom. Los botones inferiores − y + ofrecen la misma operación de escala visual.","Rueda sin modificadores","Acerca una zona antes de borrar un píxel aislado.","No cambia las dimensiones del PNG exportado.","rueda zoom acercar","zoom,quicktools");
        Add(a,c,"quicktools","Cambio rápido de herramientas","Alt + rueda alterna circularmente entre herramientas del mismo grupo sin apartar el cursor del lienzo.","Coloca el cursor sobre el lienzo y mantén Alt.|Gira hacia abajo para la siguiente herramienta o hacia arriba para la anterior.|Suelta Alt para volver al zoom normal.","Grupos: Lápiz ↔ Borrador; Selección rectangular ↔ Varita mágica; Cubeta ↔ Cuentagotas; Rectángulo → Círculo → Triángulo → Línea recta. Mover vista no cambia porque está solo. Los tamaños y propiedades se conservan, y la interfaz refleja la herramienta activa.","Alt + rueda abajo: siguiente · Alt + rueda arriba: anterior\nRueda sin modificadores: zoom","Desde Círculo, un paso hacia abajo elige Triángulo; desde Rectángulo, un paso hacia arriba elige Línea recta.","No cambia de herramienta durante un trazo, una figura, un gesto o un pegado pendiente. Confirma o cancela primero. Sobre otros paneles la rueda conserva su función.","alt rueda cambiar alternar grupos rápido","pencil,penciltips,bucket,circle,zoom");
        Add(a,c,"precision","Movimiento mediante las flechas","Ajusta puntos y selecciones con precisión de píxel.","Da el foco al lienzo y coloca el punto inicial.|Usa flechas para ajustar la posición.|Pulsa Enter para colocar o confirmar el punto según la herramienta.","Mayús aumenta el paso a 10 px. En figuras conserva el punto inicial al mover la vista. En Selección desplaza el contenido seleccionado; con Mover vista desplaza la cámara.","Flechas: 1 px · Mayús+flecha: 10 px\nBotón derecho sostenido + flechas: trazar con lápiz o borrador","Marca el centro de un círculo, aumenta el radio con flechas y confirma con Enter.","Los puntos de precisión son temporales y no se almacenan en el archivo.","teclado precisión radio extremo enter","line,circle,move,mouse");
        Add(a,c,"selectionkeys","Atajos de selección y transformaciones","Usa el teclado para copiar, pegar y confirmar contenido seleccionado.","Pulsa M y selecciona una región.|Usa Ctrl+C y Ctrl+V para reutilizarla.|Elige las transformaciones en el menú o la barra contextual.|Confirma con Enter o cancela con Esc.","Supr borra el área con Selección activa. Los giros, volteos y cambio de tamaño no tienen atajos específicos.","M · Ctrl+C/V · Enter · Esc · Supr · Flechas","Pega una baldosa y ajusta su posición un píxel con la flecha.","La capa de destino debe estar visible y desbloqueada.","atajos rotar transformar copiar pegar","selection,copy,confirm,rotateR,resizeSelection");
        Add(a,c,"history","Deshacer y rehacer","Revierte acciones recientes o recupera una acción deshecha.","Usa Editar > Deshacer para retroceder.|Usa Editar > Rehacer para recuperar el cambio si sigue disponible.","El historial es independiente por proyecto. Conserva hasta 30 acciones con un presupuesto de 64 MB de copias y al menos una acción completa; los proyectos grandes pueden disponer de menos pasos.","Ctrl+Z: deshacer · Ctrl+Y: rehacer","Deshaz una sombra completa o un trazo que no quedó bien.","Guardar una copia del proyecto es más duradero que depender del historial de la sesión.","undo redo historial revertir recuperar","save,shadow,shortcuts");
        return a;
    }
}
}
